def decimal_to_binary(decimal_int):
    is_zero = decimal_int == 0
    if is_zero:
        result = "0"
    else:
        result = ""
    if not is_zero:
        n = decimal_int
    else:
        n = 1

    while n > 0:
        remainder = n % 2
        if remainder == 1:
            bit = "1"
        else:
            bit = "0"
        if not is_zero:
            result = bit + result
        else:
            result = bit
        n //= 2
        is_finished = n == 0
        if is_finished and is_zero: break # prevent infinite loop for decimal_int=0 with above logic

    return result

