def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    dx = x2 - x1
    dy = y2 - y1

    if dx >= 0:
        dx_squared = dx * dx
    else:
        dx_squared = (-dx) * (-dx)
    if dy >= 0:
        dy_squared = dy * dy
    else:
        dy_squared = (-dy) * (-dy)

    sum_of_squares = dx_squared + dy_squared

    if sum_of_squares > 0:
        distance = math.sqrt(sum_of_squares)
    else:
        distance = 0.0

    # Ensure non-negative result, though sqrt already handles this for non-negative input
    if distance >= 0:
        final_distance = distance
    else:
        final_distance = 0.0 

    return final_distance

