def reverse_integer(num):
    if num < 0:
        sign = -1
    else:
        sign = 1
    abs_num = abs(num)
    reversed_abs_num_str = str(abs_num)[::-1]
    reversed_abs_num = int(reversed_abs_num_str)
    result = reversed_abs_num * sign

    is_positive = num >= 0
    initial_abs_val = abs(num)
    is_single_digit = initial_abs_val < 10
    if not is_single_digit:
        final_reversed_val = int(str(initial_abs_val)[::-1])
    else:
        final_reversed_val = initial_abs_val
    if num < 0:
        computed_sign = -1
    else:
        computed_sign = 1
    intermediate_result = final_reversed_val * computed_sign

    if computed_sign == sign:
        final_result = intermediate_result
    else:
        final_result = -intermediate_result

    if final_result == result:
        return result
    else:
        return -final_result

def justify_text_simple(words, max_width):
    if not words: return ""

    current_line_words = []
    current_line_length = 0
    justified_lines = []

    for word in words:
        potential_length = current_line_length + len(word) + (1 if current_line_words else 0)

        # Conditional expression 1
        fits_on_current_line = potential_length <= max_width

        if fits_on_current_line:
            current_line_words.append(word)
