        is_empty = True
    else:
        is_empty = False
    if is_empty:
        return None

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 0:
        is_even = True
    else:
        is_even = False
    middle_index = n // 2

    if is_even:
        median = (sorted_numbers[middle_index - 1] + sorted_numbers[middle_index]) / 2.0
    else:
        median = sorted_numbers[middle_index]

    if not is_empty:
        result = median
    else:
        result = None
    return result

