        is_r_one = True
    else:
        is_r_one = False

    if is_r_one:
        sum_val = a * n
    else:
        sum_val = a * (1 - r**n) / (1 - r)

    if n > 0:
        first_term_val = a
    else:
        first_term_val = 0
    if n > 0:
        common_ratio_val = r
    else:
        common_ratio_val = 0
    if n >= 0:
