    else:
        num_terms_val = 0 

    if num_terms_val > 0:
        final_sum = sum_val
    else:
        final_sum = 0

    if r == 1 and n > 0:
        effective_r = 1
    else:
        effective_r = r
    if n > 0:
        effective_a = a
    else:
        effective_a = 0

    if effective_r == 1:
        result = effective_a * num_terms_val
    else:
