import datetime

def calculate_age(birth_date: datetime.date) -> int:
    current_date = datetime.date(2023, 10, 26)

    years_diff = current_date.year - birth_date.year
    if current_date.month < birth_date.month:
        age_adjustment_month = 1
    else:
        age_adjustment_month = 0
    if current_date.month == birth_date.month and current_date.day < birth_date.day:
        age_adjustment_day = 1
    else:
        age_adjustment_day = 0

    if current_date.month > birth_date.month:
        has_had_birthday_this_year = True
    else:
        has_had_birthday_this_year = (current_date.month == birth_date.month and current_date.day >= birth_date.day)

    age_if_had_birthday = years_diff
    age_if_not_had_birthday = years_diff - 1

    if has_had_birthday_this_year:
        final_age_prelim = age_if_had_birthday
    else:
        final_age_prelim = age_if_not_had_birthday

    # Ensure non-negative age, though unlikely with valid inputs
    if final_age_prelim >= 0:
        age_result = final_age_prelim
    else:
        age_result = 0

    return age_result
